insert into iam.user_account (
    id, email, display_name, password_hash, status, locale, timezone,
    version, created_by, created_at, updated_at, last_login_at
) values (
    #{id}, #{email}, #{displayName}, #{passwordHash}, #{status}, #{locale}, #{timezone},
    #{version}, #{createdBy}, #{createdAt}, #{updatedAt}, #{lastLoginAt}
)

insert into iam.user_role (user_id, role_id, assigned_by)
select #{userId}, id, #{assignedBy}
from iam.role where code = #{roleCode}
on conflict (user_id, role_id) do nothing

insert into iam.invitation_code (
    id, code_hash, created_by, default_role, max_uses, used_count,
    expires_at, status, version, created_at
) values (
    #{id}, #{codeHash}, #{createdBy}, #{defaultRole}, #{maxUses}, #{usedCount},
    #{expiresAt}, #{status}, #{version}, #{createdAt}
)
